  source: |
    Order order = new();
    order.AddItem(new OrderItem("Book", 30m));
    order.Items.Add(new OrderItem("Pen", 5m));
    Console.WriteLine($"{order.Items.Count} {order.Total}");

    record OrderItem(string Name, decimal Price);

    class Order
    {
        private readonly List<OrderItem> _items = new();

        public decimal Total { get; private set; }

        public List<OrderItem> Items => _items;

        public void AddItem(OrderItem item)
        {
            if (item.Price <= 0)
            {
                throw new ArgumentException("Price must be positive.");
            }

            _items.Add(item);
            Total += item.Price;
        }
    }
bugLineSets: [[14]]
fixedSource: |
  Order order = new();
  order.AddItem(new OrderItem("Book", 30m));
  order.AddItem(new OrderItem("Pen", 5m));
  Console.WriteLine($"{order.Items.Count} {order.Total}");

  record OrderItem(string Name, decimal Price);

  class Order
  {
      private readonly List<OrderItem> _items = new();

      public decimal Total { get; private set; }

      public IReadOnlyList<OrderItem> Items => _items.AsReadOnly();

      public void AddItem(OrderItem item)
      {
          if (item.Price <= 0)
          {
              throw new ArgumentException("Price must be positive.");
          }

          _items.Add(item);
          Total += item.Price;
      }
  }
fixedExpect: { kind: output, value: "2 35" }
